SELECT 'batch_013_0fb87970_wav_10' AS batch_id,(SELECT COUNT(*) FROM song_masters WHERE id IN ('sm-upload-1128b5a0-ce0','sm-upload-1cd9d081-b6d','sm-upload-206e47d9-a48','sm-upload-432ba270-b5e','sm-upload-5615bc1e-d29','sm-upload-5fdc3794-8b3','sm-upload-8f59da34-f13','sm-upload-9094c1a3-3a5','sm-upload-96f3cedc-994','sm-upload-c3ebd766-3c7') AND album_id='al-216f4095bcd91c9197f8cb640fb87970') AS candidate_masters_in_target,(SELECT COUNT(*) FROM song_masters WHERE id IN ('sm-upload-1128b5a0-ce0','sm-upload-1cd9d081-b6d','sm-upload-206e47d9-a48','sm-upload-432ba270-b5e','sm-upload-5615bc1e-d29','sm-upload-5fdc3794-8b3','sm-upload-8f59da34-f13','sm-upload-9094c1a3-3a5','sm-upload-96f3cedc-994','sm-upload-c3ebd766-3c7') AND album_id='pending-uploads') AS candidate_masters_still_pending,(SELECT COUNT(*) FROM albums WHERE id='al-216f4095bcd91c9197f8cb640fb87970' AND name='心语') AS target_album_rows,(SELECT song_count FROM albums WHERE id='al-216f4095bcd91c9197f8cb640fb87970') AS stored_song_count,(SELECT COALESCE(SUM(si.size),0) FROM song_instances si JOIN song_masters sm ON sm.id=si.master_id WHERE sm.album_id='al-216f4095bcd91c9197f8cb640fb87970') AS calculated_size;
